// Every photo and video from the night. Files are generated by scripts/process-media.mjs
// from the raw phone media in ./media; this file adds tags and captions on top.

import raw from './media.json'

export type Tag = 'track' | 'carnage' | 'wave' | 'podium' | 'paddock' | 'screen' | 'overview'

export interface MediaItem {
  id: string
  kind: 'photo' | 'video'
  src: string
  thumb: string
  w: number
  h: number
  duration?: number
  tags: Tag[]
  caption: string
}

