const TRACK_LINES = [
  'Racing line: optional.',
  'Apex? Never heard of her.',
  'Somewhere in here is a black flag waiting to happen.',
  'The hairpin claims another victim.',
  'Late on the brakes, early on the excuses.',
  'Nose to tail through the kerbs.',
  'A rare moment of green-flag racing.',
  'Formation flying, karting edition.',
  'Traffic, TeamSport style.',
  'Tyre wall getting nervous.',
  'Is that a gap? It’s a gap if you believe.',
  'Concentration face: engaged.',
]

export const MEDIA: MediaItem[] = (raw as Omit<MediaItem, 'tags' | 'caption'>[]).map((m, i) => {
  const c = CURATED[m.id]
  return { ...m, tags: c?.[0] ?? ['track'], caption: c?.[1] ?? TRACK_LINES[i % TRACK_LINES.length] }
})

export const byId = (id: string) => MEDIA.find((m) => m.id === id)!
export const PHOTOS = MEDIA.filter((m) => m.kind === 'photo')
export const VIDEOS = MEDIA.filter((m) => m.kind === 'video')
export const withTag = (t: Tag) => MEDIA.filter((m) => m.tags.includes(t))

export const HERO_VIDEO = byId('m104')
export const SQUAD = byId('m001')
export const PODIUM_SET = ['m007', 'm006', 'm005', 'm004', 'm008'].map(byId)
export const CARNAGE = withTag('carnage')
